import pandas as pd,numpy as np,matplotlib.pyplot as plt
from pathlib import Path
R=Path(__file__).resolve().parents[1];O=R/'phase1d_signal_coverage';e=pd.read_parquet(R/'outputs/tables/dataset_a_events_with_gt.parquet').sort_values(['session_id','timestamp_ms','raw_line_number']).reset_index(drop=True);e['p']=e.groupby('session_id').execution_id.shift();e['pt']=e.groupby('session_id').timestamp_ms.shift();e['gap']=((e.timestamp_ms-e.pt)/1000).clip(0,120);e['boundary']=e.execution_id.notna()&e.p.notna()&e.execution_id.ne(e.p);e['temporal_gap']=e.gap>1;e['app_context_change']=e.active_app.ne(e.groupby('session_id').active_app.shift());e['window_change']=e.window_title.ne(e.groupby('session_id').window_title.shift());e['browser_activity']=e.event_type.isin(['browser_navigation','browser_form_input','browser_click']);e['clipboard']=e.event_type.eq('clipboard_change');e['density_change']=e.gap>e.groupby('session_id').gap.transform(lambda x:x.quantile(.9));e['interaction_change']=e.event_type.ne(e.groupby('session_id').event_type.shift());s=['temporal_gap','density_change','app_context_change','window_change','browser_activity','clipboard','interaction_change'];rows=[]
for z in s:
 rows.append({'signal':z,'boundary_coverage':e.loc[e.boundary,z].mean(),'candidate_count':int(e[z].sum()),'candidate_density':e[z].mean()})
e['any']=e[s].any(axis=1);miss=e[e.boundary&~e['any']].copy();miss[['session_id','timestamp_iso','gap','active_app','window_title','event_type','p','execution_id']].to_csv(O/'boundary_examples.csv',index=False);miss.groupby(['event_type','active_app']).size().reset_index(name='missed_count').sort_values('missed_count',ascending=False).to_csv(O/'missed_boundary_analysis.csv',index=False);pd.DataFrame(rows).to_csv(O/'signal_coverage.csv',index=False);fig,ax=plt.subplots();ax.bar([r['signal'] for r in rows],[r['boundary_coverage'] for r in rows]);ax.tick_params(axis='x',rotation=45);ax.set_ylabel('GT boundary coverage');fig.tight_layout();fig.savefig(O/'plots/signal_coverage.png',dpi=160);print(len(miss),pd.DataFrame(rows).sort_values('boundary_coverage',ascending=False).to_dict('records'))
